--
-- Name: encrypt_password(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.encrypt_password() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.password IS NOT NULL THEN
    NEW.password := crypt(NEW.password, gen_salt('bf'));
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.encrypt_password() OWNER TO postgres;

--
-- Name: generate_user_code(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_user_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

  IF NEW.role_id = (SELECT id FROM roles WHERE name = 'Admin') THEN
    NEW.user_code := 'AM-' || LPAD(nextval('users_user_code_seq')::TEXT, 6, '0');
  ELSIF NEW.role_id = (SELECT id FROM roles WHERE name = 'Super Admin') THEN
    NEW.user_code := 'SAM-' || LPAD(nextval('users_user_code_seq')::TEXT, 6, '0');
  ELSE
    NEW.user_code := 'USR-' || LPAD(nextval('users_user_code_seq')::TEXT, 6, '0');
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.generate_user_code() OWNER TO postgres;

--
-- Name: generate_user_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_user_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    next_id INT;
BEGIN
    -- เอาค่า id ล่าสุด
    SELECT COALESCE(MAX(id), 0) + 1 INTO next_id FROM users;
    
    -- ตั้งค่า user_id รูปแบบ U00001
    NEW.user_id := 'U' || LPAD(next_id::TEXT, 5, '0');
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.generate_user_id() OWNER TO postgres;

